{
  "up": "Select molecule_chembl_id as chembl_id, molecule_dictionary.pref_name as compound_name, compound_structures.canonical_smiles as canonical_smiles from molecule_dictionary join compound_records on molecule_dictionary.molregno = compound_records.molregno join docs on compound_records.doc_id = docs.doc_id join activities on compound_records.record_id = activities.record_id where docs.chembl_id = 'CHEMBL5729625' and compound_structures.molregno = molecule_dictionary.molregno and compound_structures.canonical_smiles is not null group by molecule_chembl_id, compound_name, canonical_smiles order by chembl_id, compound_name, canonical_smiles"
}
